# Blog posts — GLP-1 and GLP-1 combination medicines. One practical, patient-journey post per product.
# Facts stay within the product label data in data_drugs.py; general tips are standard patient guidance.

def post(slug, drug, title, desc, tldr, sections, faqs, tags):
    return {"slug": slug, "drug": drug, "title": title, "desc": desc, "tldr": tldr, "sections": sections,
            "faqs": [{"q": q, "a": a} for q, a in faqs], "tags": tags}

NAUSEA_TIPS = ("<ul><li>Eat smaller meals and stop as soon as you feel full — the medicine makes fullness arrive earlier.</li>"
               "<li>Go easy on fatty, fried and very sweet foods in the days after a dose increase.</li>"
               "<li>Sip water through the day; vomiting or diarrhea can dehydrate you and strain the kidneys.</li>"
               "<li>Tell your prescriber if nausea lasts — staying on a lower dose longer is a common fix.</li></ul>")

